import { atom, read, update } from 'claude-code'
import type { Register, Timer, EngineInterface } from 'claude-code'

import type { Mood, PetState } from '../types'

const PANE = 'code-pet'
const SETTLE_MS = 7000
const SLOW_CALL_MS = 3500
// Tall enough for the whole pet: sparkles + face + up to 4 lines of thought + streak + buttons.
const PANE_ROWS = 9
// AI thoughts are cheap but not free: at most one Haiku call per this window.
const THINK_EVERY_MS = 8000
// A tip after each reply stays up this long before the cat curls back up.
const TIP_HOLD_MS = 120000
// How much of the reply's end Haiku reads when suggesting a next step.
const TIP_CONTEXT_CHARS = 2000

const pet = atom({ plugin: 'code-pet', key: 'mood' } as const, {
  mood: 'neutral',
  thought: 'curled up, waiting...',
  streak: 0,
} as PetState)

const FACES: Record<Mood, string> = {
  neutral: '(=^･ｪ･^=)',
  happy: '(=^ᵔωᵔ^=)',
  excited: '(=^ ↀ ω ↀ ^=)',
  concerned: '(=^･ω･^=;)',
  sleepy: '(=^-ω-^=)',
  loved: '(=^ ˘ ω ˘ ^=)',
}

const COLORS: Record<Mood, string> = {
  neutral: '#b794f6',
  happy: '#3ec79f',
  excited: '#ff7ad9',
  concerned: '#f0855e',
  sleepy: '#7b9cff',
  loved: '#ff9eb5',
}

const SPARKLES: Record<Mood, string> = {
  neutral: '· · ·',
  happy: '✿ ✿ ✿',
  excited: '✦ ✧ ✦',
  concerned: '! ? !',
  sleepy: 'z z Z',
  loved: '♡ ♡ ♡',
}

const IDLE_THOUGHT = 'curled up, waiting...'

const PAT_LINES = ['purrrr~ ♡', '*leans into your hand*', 'mrrp! more pats pls', '*slow blink* ♡', '*happy kneading*']
const TREAT_LINES = ['nom nom nom!', '*crunch crunch* tysm', 'treat!! (=^･ω･^=)', 'mew! my favorite flavor']

function pick(lines: readonly string[]): string {
  return lines[Math.floor(Math.random() * lines.length)] ?? lines[0] ?? ''
}

const SYSTEM =
  'You are a tiny, cute cat that lives in a programmer\'s terminal and watches them code. ' +
  'Talk like a cat: mew, purr, paws, whiskers, naps, zoomies, a cat kaomoji now and then. ' +
  'Reply with ONE short reaction, 3 to 9 words, lowercase, playful, maybe one kaomoji or emoji. ' +
  'No quotes, no explanations, never more than one line.'

const TIP_SYSTEM =
  'You are a tiny, cute cat that lives in a programmer\'s terminal. You just read the AI assistant\'s latest reply. ' +
  'Suggest ONE concrete, useful next step for the human, in at most 14 words, lowercase, cat-flavored but clear. ' +
  'No quotes, no preamble, one line only.'

type TimeOfDay = 'morning' | 'afternoon' | 'evening' | 'night'

function timeOfDay(): TimeOfDay {
  const hour = new Date().getHours()
  if (hour >= 5 && hour < 12) return 'morning'
  if (hour >= 12 && hour < 17) return 'afternoon'
  if (hour >= 17 && hour < 22) return 'evening'
  return 'night'
}

const GREETINGS: Record<TimeOfDay, string> = {
  morning: 'mew! good morning ☀',
  afternoon: 'mew! good afternoon~',
  evening: 'mew! good evening ☾',
  night: 'mew... up late? ☾',
}

function feel(mood: Mood, thought: string, streak: number): PetState {
  return { mood, thought, streak }
}

// Always mirror the pet's mood to the status line too, so it's visible even
// when the terminal is too narrow to place the pane that opened unasked.
async function setPet($: EngineInterface, change: (s: PetState) => PetState) {
  const state = await update($, pet, change)
  $.ui.status(`${FACES[state.mood]} mew`)
  return state
}

let settleTimer: Timer | undefined

function settleLater($: EngineInterface, ms = SETTLE_MS) {
  settleTimer?.cancel()
  settleTimer = $.clock.after(ms, () => {
    void setPet($, s => (s.mood === 'sleepy' ? s : feel('neutral', IDLE_THOUGHT, s.streak)))
  })
}

let lastThinkAt = -Infinity
let thinkSeq = 0

function clean(text: string): string {
  const line = text.trim().split('\n')[0] ?? ''
  const unquoted = line.replace(/^["'“”]+|["'“”]+$/g, '').trim()
  return unquoted.length > 160 ? `${unquoted.slice(0, 157)}...` : unquoted
}

// Ask Haiku for a fresh one-liner about what just happened. The canned thought
// is already showing; this only replaces it if the pet is still in that mood.
async function think($: EngineInterface, mood: Mood, happening: string) {
  const now = await $.clock.now()
  if (now - lastThinkAt < THINK_EVERY_MS) return
  lastThinkAt = now
  const seq = ++thinkSeq

  const r = await $.model.complete({
    model: 'haiku',
    system: SYSTEM,
    prompt: `It is ${timeOfDay()}. You feel ${mood}. What just happened: ${happening}. React.`,
    maxTokens: 40,
    effort: 'low',
    timeoutMs: 6000,
  })
  if (!r.isAnswered) return
  const thought = clean(r.text)
  if (!thought || seq !== thinkSeq) return
  await setPet($, s => (s.mood === mood ? { ...s, thought } : s))
}

// After each finished reply, Haiku reads the end of it and the cat offers a next step.
async function suggest($: EngineInterface, answer: string) {
  const seq = ++thinkSeq
  const r = await $.model.complete({
    model: 'haiku',
    system: TIP_SYSTEM,
    prompt: `The assistant's latest reply (its end):\n\n${answer.slice(-TIP_CONTEXT_CHARS)}\n\nYour one-line suggestion:`,
    maxTokens: 60,
    effort: 'low',
    timeoutMs: 8000,
  })
  if (!r.isAnswered) return
  const tip = clean(r.text)
  if (!tip || seq !== thinkSeq) return
  await setPet($, s => feel('happy', `💡 ${tip}`, s.streak))
  settleLater($, TIP_HOLD_MS)
}

async function pat($: EngineInterface) {
  ++thinkSeq
  await setPet($, s => feel('loved', pick(PAT_LINES), s.streak))
  settleLater($)
}

async function treat($: EngineInterface) {
  ++thinkSeq
  await setPet($, s => feel('excited', pick(TREAT_LINES), s.streak))
  settleLater($)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'pet',
      description: 'Open the code-pet pane',
    })
    await setPet($, () => feel('happy', GREETINGS[timeOfDay()], 0))
    settleLater($)
    const opened = await $.ui.open({ id: PANE, title: 'Pet', rows: PANE_ROWS })
    if (!opened.isPlaced) $.ui.toast('code-pet: window too narrow to open on its own — run /pet to open it')

    return next(e)
  })

  on('command.run', { command: 'pet' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Pet', focus: true, rows: PANE_ROWS })

    return { text: 'Pet pane opened.' }
  })

  on('turn.start', async ($, e, next) => {
    const s = await setPet($, s => (s.mood === 'sleepy' ? s : feel('excited', 'ears up! let\'s see...', s.streak)))
    settleLater($)
    void think($, s.mood, 'the human just sent a new message')

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const label = String(e.tool).replace(/^mcp__[^_]+__/, '')
    let stillRunning = true
    const slowTimer = $.clock.after(SLOW_CALL_MS, () => {
      if (stillRunning) void setPet($, s => feel('sleepy', `watching ${label}... *tail swish*`, s.streak))
    })

    const ran = await next(e)
    stillRunning = false
    slowTimer.cancel()

    if (ran.deny !== undefined) return ran

    const hasFailed = ran.isError === true
    const s = await setPet($, s => {
      if (hasFailed) return feel('concerned', `hiss... ${label} didn't go well`, 0)
      const streak = s.streak + 1
      return streak >= 3
        ? feel('excited', `zoomies! (${streak} in a row)`, streak)
        : feel('happy', `purr~ ${label} worked`, streak)
    })
    settleLater($)
    // Only the tool's name and outcome go to Haiku, never its input or output.
    void think(
      $,
      s.mood,
      hasFailed ? `the ${label} tool failed` : `the ${label} tool worked, ${s.streak} successes in a row`,
    )

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId && !e.isAborted && e.reason === 'answer' && e.answer.trim()) void suggest($, e.answer)

    return done
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const state = await read($, pet)
    const color = COLORS[state.mood]

    return (
      <Box
        flexDirection="column"
        alignItems="center"
        flexGrow={1}
        paddingX={1}
      >
        <Text color={color}>{SPARKLES[state.mood]}</Text>
        <Box flexGrow={1} alignItems="center" justifyContent="center">
          <Button key="face" plain label={FACES[state.mood]} hover={{ scope: 'face', color }} onPress={() => void pat($)} />
        </Box>
        <Text italic color={color} wrap="wrap">
          {state.thought}
        </Text>
        {state.streak > 0 ? <Text dimColor>{`♥ ×${state.streak}`}</Text> : null}
        <Box flexDirection="row">
          <Button key="pat" plain hotkey="p" label="pat" onPress={() => void pat($)} />
          <Text>{'   '}</Text>
          <Button key="treat" plain hotkey="t" label="treat" onPress={() => void treat($)} />
        </Box>
      </Box>
    )
  })
}

