export type Mood = 'neutral' | 'happy' | 'excited' | 'concerned' | 'sleepy' | 'loved'

export type PetState = {
  mood: Mood
  thought: string
  streak: number
}

declare module 'claude-code' {
  interface PluginState {
    'code-pet': { mood: PetState }
  }
}
